import json,pathlib
root=pathlib.Path(__file__).resolve().parent
specs=json.loads((root/'specs.json').read_text(encoding='utf-8'))
def add(group,ident,motif,ref='card_jigger.png',slug=None):
 prefix={'card':'card_','research':'research_','research_tea':'research_','mastery':'mastery_'}[group]
 name=prefix+(slug or ident)+('_tea' if group=='research_tea' else '')
 specs.append(dict(file=name,id=ident,group=group,reference=ref,description=motif))
for ident,slug,motif,ref in [
 ('bar_shoes','build','One low rocks glass with amber drink and two ice cubes, a small bottle tilted directly over the serving glass with a short connected stream, a citrus wedge on the rim. Build cocktail technique made directly inside the serving glass; no shaker.','card_jigger.png'),
 ('champagne_spray','split_base','Two distinctly shaped small spirit bottles, one tall narrow gin bottle and one squat amber rum bottle, each pouring its own narrow stream into a single central mixing glass. Clearly two bases combined, not champagne spray.','card_jigger.png'),
 ('liqueur','liqueur','A single squat elegant ruby liqueur bottle with rounded shoulders and a short cork, beside a small orange peel curl and one green herb sprig, tiny stemmed tasting glass with red liqueur. The label is a plain blank cream patch.','card_jigger.png'),
 ('molotov','flamed_zest','A curved fresh orange peel held above one low amber cocktail glass; a very small bright orange flame crosses a short spray of citrus oil between the peel and glass. Cocktail aromatic zest technique, no weapon or firebomb.','card_jigger.png'),
 ('syrup','prebatch','A large capped clear glass carafe half filled with amber mixed cocktail base, beside three matching tiny empty low glasses in a neat row. Preparing multiple servings ahead, not a syrup jar.','card_jigger.png'),
 ('dried_leaf','leaf_drying','A low round woven bamboo drying tray covered with spread-out separate curled sage green tea leaves, one wooden leaf rake across its edge. Dry tea processing, no sun symbol, no cooked food.','card_gaiwan.png'),
 ('golden_ratio','brew_balance','A small porcelain tea brewing pot on a compact weighing scale, with a tiny hourglass and slim thermometer standing clearly beside it, a few tea leaves in front. Measuring tea quantity, water temperature and steeping time together. No digits.','card_gaiwan.png'),
 ('honey','teaspoon','One long silver measuring teaspoon shown diagonally, bowl filled with distinct dry green tea leaves, above a small open ceramic leaf jar. Clearly spoon measuring tea leaves, no honey, no dripping liquid.','card_gaiwan.png'),
 ('long_spout','long_spout','A single round polished silver gooseneck kettle with a very long thin curved spout on the right pouring a narrow connected stream into a little ivory tea cup below. Main silhouette must be the long curved spout.','card_gaiwan.png'),
 ('nightshade_blend','black_tea_finish','An ivory handleless tea tasting cup filled with deep copper red black tea, beside distinct curled dark oxidized tea leaves and a single tall curling wisp of fragrant steam. Plain tea, no poisonous plant, no skull.','card_gaiwan.png'),
 ('piercing_arrowhead','tea_strainer','A single fine mesh spherical tea infuser ball opened into two hinged hemispheres, with green tea leaves in one half and a short attached chain ending in a small hook. Clearly tea filtering tool, not a cocktail spring strainer or weapon.','card_gaiwan.png'),
 ('tea_leaf_scatter','blending','Three separate small piles of rolled green tea, narrow dark black tea, and pale dried flower petals arranged around one central wooden blending scoop partly filled with mixed leaves. Three visibly different ingredient textures.','card_gaiwan.png'),
 ('warm_cup','cup_warming','A tilted small ivory pitcher pouring a connected stream of clear hot water into an empty wide ivory handleless tea cup on its saucer, two soft steam curls rise from the receiving cup. Warming an empty tea cup before brewing, no tea leaves in cup.','card_gaiwan.png')]: add('card',ident,motif,ref,slug)
for ident,motif in [
 ('ristretto','A short thick concentrated dark coffee stream dripping from a small metal portafilter into one tiny clear espresso shot glass, only a shallow very dark coffee layer and golden crema. Compact intense extraction, a small brass speed wing detail beside the glass.'),
 ('balanced_extraction','An elegant small brass balance scale with two level pans, one holds a clear water droplet and the other a neutral cream measuring scoop. Straight balanced beam and long horizontal silhouette, no coffee beans or tea leaves.'),
 ('full_body_roast','A heavy dark iron roasting pan tilted slightly, several large glossy brown roasted coffee beans tumbling out beside two warm roasting heat curls. Coffee roasting tools, no cup, no flames.'),
 ('perfect_extraction','A polished espresso portafilter with a split twin spout pouring two distinct dark coffee streams into two tiny matching ivory espresso cups with golden crema. Twin complete pours show additional strike effect.'),
 ('caffeine_rush','Three large glossy roasted coffee beans with two clear curved forward motion streaks and one tiny gold lightning spark. Dynamic rushing diagonal coffee bean cluster, no cup or teapot.'),
 ('doppio_body','Two small sturdy ivory espresso cups side by side on one broad saucer, each filled with dark coffee and thick golden crema, a small warm red heart motif nestled between the cups. Clearly double shot coffee vitality.'),
 ('mellow_finish','A plain ivory handleless warm beverage bowl with soft pale steam curling into a simple small heart, on a smooth saucer. Neutral light amber liquid, no coffee beans or specific tea utensils. Gentle warmth and recovery.'),
 ('insulated_cup','One sturdy double wall insulated ivory travel tumbler with a clearly visible thick inner rim, fitted dark lid tilted beside it and a protective sage sleeve. No logo, no coffee beans. Neutral vessel for coffee or tea.'),
 ('steady_hand','One steady gloved cafe hand carefully holding a small neutral silver pouring pitcher above a tiny ivory cup, with a single perfectly straight narrow connected water stream. Stable precise pour, no motion streaks. Hand anatomically simple mitten-like.'),
 ('cold_brew','A tall clear sealed cold infusion bottle half filled with neutral pale amber liquid, a suspended filter pouch inside and two large separate pale blue ice cubes at its base. Neutral cold water extraction, no obvious coffee bean or tea leaf identity.'),
 ('fine_grind','A compact wooden hand coffee grinder with a short horizontal crank and brass knob, open lower drawer showing finely ground brown coffee and two whole beans beside it. Clearly mechanical grinding tool.'),
 ('wide_tray','A broad oval polished silver cafe serving tray viewed slightly from side with thick raised rim and two short side handles. Three tiny neutral ingredient containers spaced across the tray emphasize its generous pickup area.'),
 ('measured_pour','A small graduated clear measuring pitcher tilted over a tiny neutral ivory cup, a single straight narrow connected stream and three short horizontal measurement tick marks without digits on the pitcher. Precise volume measurement, no jigger.'),
 ('zero_waste','A tilted small glass brewing server almost completely empty, one final large amber droplet falling from its lip into a tiny ivory cup, a small flexible silicone scraper tucked beside the server. Last drop collection, no leaf or bean identity.')]: add('research',ident,motif)
for ident,motif in [
 ('ristretto','A tiny ivory lidded tea steeping pot releasing one short deep amber tea stream into a single small handleless cup, with dense compressed tea leaves beside the pot. Concentrated infusion, no espresso portafilter, no coffee beans.'),
 ('full_body_roast','A round compressed aged dark tea leaf cake with a clean broken wedge showing layered leaf texture, beside a small open paper wrap and a dark wooden tea pick. Deep tea aging, no roasting pan or coffee beans.'),
 ('perfect_extraction','An ivory lidded tea brewing pot with a removable sage leaf infuser basket beside it and two tiny tasting cups filled evenly with golden tea. Fully infused tea shared between two cups, no coffee apparatus.'),
 ('caffeine_rush','A bright fresh green tea leaf sprig above a small handleless tea bowl, three sweeping rising aroma curls and two short forward motion strokes. Tea fragrance and vitality, no coffee bean or lightning-shaped cup.'),
 ('doppio_body','Three nested curling layers of pale fragrant steam rising from one small ivory tea aroma cup, a pair of overlapping fresh green leaves at its base and a small warm heart in the steam. Layered tea fragrance and vitality, no espresso cups.'),
 ('fine_grind','A shallow bamboo tea sorting basket with a few carefully separated long green tea leaves, one slender wooden tweezer selecting a complete leaf above the basket. Tea leaf selection, no grinder or coffee beans.')]: add('research_tea',ident,motif,'card_gaiwan.png')
for ident,motif in [
 ('service_1','A cafe serving hand presenting a small freshly filled ivory cup on a silver saucer, beside a compact hourglass with most sand still in the upper bulb. Energetic first service at the beginning, no numeral.'),
 ('service_2','A welcoming cafe service bell next to a small blank loyalty card displaying exactly three punched circular marks, one familiar ivory customer cup nearby. Repeat service rhythm and regular customer recognition, no text.'),
 ('service_3','An elegant completed signature cocktail glass with a distinctive twisted citrus garnish, next to a small folded recipe note bearing three simple ingredient silhouettes connected by a check mark. Preparing chosen signature combination, no letters.'),
 ('service_4','A compact silver closing service bell beside a small dark cafe clock showing hands close to closing time and a neat stack of empty cups. One small sharp gold emphasis glint, final service concentration, no digits.'),
 ('stability_1','A cafe tray carried level with a cup of amber tea whose liquid surface stays perfectly flat, a folded ivory service cloth below and one small hourglass beside it. Calm unhurried steady service, no person body.'),
 ('stability_2','An ivory handled cup tipped gently to reveal only one last amber sip at its bottom, backed by a small sturdy curved sage shield. Last sip protective reserve, no full drink or spilled liquid.'),
 ('stability_3','A steaming small ivory cup resting on a folded cafe towel beside a little wall clock and a single fresh leaf. Rest break and recovery after hard service, no weapons or boss monster.'),
 ('stability_4','A dark cafe work shoe stepping firmly forward beside a small upright cup, a curved return path arrow sweeping behind the shoe and a tiny warm heart near its heel. Composed return to service under pressure, no numeric symbols.'),
 ('finesse_1','One precise silver teaspoon placing a single round amber droplet exactly at the center of a small cream saucer marked with a subtle concentric target. First exact contact, clean complete utensil, no text or hands.'),
 ('finesse_2','A long silver bar spoon stretched horizontally between a small serving cup and a distant tiny saucer, a simple double ended distance arrow below the spoon. Distance control through clear spacing and long tool silhouette, no text or numbers.'),
 ('finesse_3','Four distinctly shaped miniature served drinks on a tray: stemmed red cocktail, low amber rocks glass, green handleless tea bowl, and tall clear infusion glass. Varied cafe service, four unmistakable silhouettes, no confetti.'),
 ('finesse_4','One carefully finished amber beverage in a small ivory cup centered under a compact brass cafe task lamp casting a narrow warm spotlight onto the cup only. Focus on a single prepared drink, no floor or backdrop.')]: add('mastery',ident,motif)
assert len(specs)==48 and len({x['file'] for x in specs})==48
(root/'specs.json').write_text(json.dumps(specs,ensure_ascii=False,indent=2),encoding='utf-8')
print('48 unique file specs')
